referenceSolutionTemplate:
#include <iostream>
using namespace std;

bool loud = true;

void say(const char* s) {
    if (loud) {
        cout << s << endl;
    } else {
        cout << "……" << endl;
    }
}

struct Quiet {
    bool old;
    Quiet() : old(loud) {
        loud = false;
    }
    ~Quiet() {
        loud = old;
    }
};

int main() {
    say("{word}");
    {
        Quiet q;
        say("{word}");
    }
    say("{word}");
    return 0;
}
